 boolean result(int req,int res,Intent data){if(req<20||req>22)return false;if(res!=Activity.RESULT_OK||data==null||data.getData()==null)return true;final int g=a.generation;final String path=uploadPath;final JSONObject payload=uploadData;Uri uri=data.getData();a.busy=true;a.loading.setVisibility(View.VISIBLE);a.notice("Preparando arquivo…",false);a.io.execute(()->{try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=a.getContentResolver().openInputStream(uri)){byte[] b=new byte[8192];int n;int max=req==20?26214400:req==21?200000:8000000;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("Arquivo acima do limite.");out.write(b,0,n);}}if(req==22){Bitmap source=a.art.decode(out.toByteArray(),true);if(source==null)throw new IOException("Foto inválida.");float ratio=Math.min(1,320f/Math.max(source.getWidth(),source.getHeight()));Bitmap small=Bitmap.createScaledBitmap(source,Math.max(1,(int)(source.getWidth()*ratio)),Math.max(1,(int)(source.getHeight()*ratio)),true);ByteArrayOutputStream jpg=new ByteArrayOutputStream();small.compress(Bitmap.CompressFormat.JPEG,75,jpg);if(jpg.size()>130000)throw new IOException("Escolha uma foto menor.");String encoded=android.util.Base64.encodeToString(jpg.toByteArray(),2);a.runOnUiThread(()->{if(g!=a.generation)return;a.busy=false;a.loading.setVisibility(View.GONE);pendingAvatar[0]=encoded;a.publicProfiles.photoChanged(encoded);a.notice("Foto pronta. Salve o perfil para publicar.",false);});return;}if(req==21)payload.put("subtitles",out.toString("UTF-8"));else{payload.put("video",android.util.Base64.encodeToString(out.toByteArray(),2));if(path.endsWith("/upload")&&payload.optInt("duration_seconds")==0){android.media.MediaMetadataRetriever metadata=new android.media.MediaMetadataRetriever();try{metadata.setDataSource(a,uri);String duration=metadata.extractMetadata(android.media.MediaMetadataRetriever.METADATA_KEY_DURATION);if(duration!=null)payload.put("duration_seconds",Math.max(1,Long.parseLong(duration)/1000));}finally{metadata.release();}}}a.runOnUiThread(()->{if(g!=a.generation)return;a.busy=false;a.loading.setVisibility(View.GONE);post(path,payload,r->a.notice("Arquivo salvo. Volte ao estúdio para continuar.",false));});}catch(Exception ex){a.runOnUiThread(()->{if(g!=a.generation)return;a.busy=false;a.loading.setVisibility(View.GONE);a.notice(ex.getMessage(),true);});}});return true;}
 void analytics(){page("analytics","Seu público","Dados de reprodução sincronizados pelos espectadores.",()->a.profile());get("/analytics",r->{a.title(a.body,r.optInt("followers")+" seguidores",24);JSONArray items=r.getJSONArray("items");for(int i=0;i<items.length();i++){JSONObject s=items.getJSONObject(i);a.title(a.body,s.optString("title"),20);LinearLayout metrics=a.row();String[] labels={"Espectadores","Concluídos","Curtidas"},keys={"viewers","completed","likes"};for(int k=0;k<3;k++){LinearLayout tile=a.col();tile.setPadding(a.dp(10),a.dp(14),a.dp(10),a.dp(14));tile.setBackground(a.outline(CARD,14));a.title(tile,String.valueOf(s.optInt(keys[k])),24);a.text(tile,labels[k],11,MUTED);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.rightMargin=a.dp(6);metrics.addView(tile,lp);}a.body.addView(metrics);a.gap(a.body,18);}if(items.length()==0)a.text(a.body,"Publique sua primeira produção para acompanhar o público.",14,MUTED);});}
