 void editorial(){page("editorial","Organize o início","Destaque e coleções escolhidos por você.",()->a.admin());get("/editorial",r->a.fetchAll("/catalog",new JSONArray(),catalog->{editorialShows=catalog.getJSONArray("items");String[] names=new String[editorialShows.length()+1];names[0]="Escolha automática";int selected=0;for(int i=0;i<editorialShows.length();i++){JSONObject show=editorialShows.getJSONObject(i);names[i+1]=show.optString("title");if(show.optInt("id")==r.getJSONObject("config").optInt("featured_id"))selected=i+1;}Spinner featured=a.select(a.body,"PRODUÇÃO EM DESTAQUE",names,names[selected]);a.button(a.body,"Salvar destaque",RED,()->a.safe(()->{int index=featured.getSelectedItemPosition();post("/editorial",a.obj("featured_id",index==0?JSONObject.NULL:editorialShows.getJSONObject(index-1).getInt("id")),ok->editorial());}));a.button(a.body,"＋  Nova coleção",CARD,()->collection(null));JSONArray cs=r.getJSONArray("items");for(int i=0;i<cs.length();i++){JSONObject c=cs.getJSONObject(i);a.button(a.body,c.optString("title")+(c.optBoolean("active")?"":" • oculta"),CARD,()->collection(c));}}));}
 void collection(JSONObject c){page("collection","Coleção editorial","Escolha as séries e a posição desta faixa no início.",()->editorial());EditText title=input("TÍTULO","Romances para maratonar",80),position=input("POSIÇÃO NO INÍCIO","0",4),description=input("DESCRIÇÃO","Por que estas histórias estão juntas?",500);description.setText(c==null?"":c.optString("description"));position.setInputType(2);position.setText(c==null?"0":c.optString("position"));CheckBox active=new CheckBox(a);active.setText("Exibir no início");active.setTextColor(WHITE);active.setChecked(c==null||c.optBoolean("active"));a.body.addView(active);Set<Integer> selected=new LinkedHashSet<>();if(c!=null){title.setText(c.optString("title"));JSONArray ids=c.optJSONArray("show_ids");if(ids!=null)for(int i=0;i<ids.length();i++)selected.add(ids.optInt(i));}TextView summary=a.text(a.body,selected.size()+" produções selecionadas",13,MUTED);a.button(a.body,"Escolher produções",CARD,()->{String[] names=new String[editorialShows.length()];boolean[] checked=new boolean[names.length];for(int i=0;i<names.length;i++){JSONObject show=editorialShows.optJSONObject(i);names[i]=show.optString("title");checked[i]=selected.contains(show.optInt("id"));}new AlertDialog.Builder(a).setTitle("Produções da coleção").setMultiChoiceItems(names,checked,(d,n,on)->{int id=editorialShows.optJSONObject(n).optInt("id");if(on)selected.add(id);else selected.remove(id);}).setPositiveButton("Concluir",(d,n)->summary.setText(selected.size()+" produções selecionadas")).show();});a.button(a.body,"Salvar coleção",RED,()->a.safe(()->{JSONArray ids=new JSONArray();for(int id:selected)ids.put(id);JSONObject data=a.obj("title",title.getText().toString(),"description",description.getText().toString(),"show_ids",ids,"position",Integer.parseInt(position.getText().toString()),"active",active.isChecked());if(c!=null)data.put("id",c.getInt("id"));post("/editorial",data,ok->editorial());}));}
