 int stamp(String s){String[] parts=s.trim().split(" ");String[] t=parts[0].split(":");if(t.length<2)throw new IllegalArgumentException();double seconds=Double.parseDouble(t[t.length-1]);int minutes=Integer.parseInt(t[t.length-2]),hours=t.length>2?Integer.parseInt(t[t.length-3]):0;return (int)((hours*3600+minutes*60+seconds)*1000);}
 void parseSubtitles(String value){cues.clear();for(String block:value.replace("\r","").split("\n\s*\n")){String[] lines=block.split("\n");for(int i=0;i<lines.length;i++)if(lines[i].contains("-->")){try{String[] times=lines[i].split("-->");int start=stamp(times[0].trim()),end=stamp(times[1].trim().split(" ")[0]);StringBuilder words=new StringBuilder();for(int j=i+1;j<lines.length;j++)words.append(lines[j]).append('\n');if(end>start)cues.add(new Cue(start,end,android.text.Html.fromHtml(words.toString().trim(),0).toString()));}catch(Exception ignored){}break;}}}
