 JSONObject pending(){try{return new JSONObject(a.prefs.getString(a.local("pending_progress"),"{}"));}catch(Exception ex){return new JSONObject();}}
 void flushProgress(Runnable done){JSONObject queued=pending();if(queued.length()==0){done.run();return;}final int page=a.generation;final String key=a.local("pending_progress"),viewer=a.viewerToken,account=a.uid;a.io.execute(()->{try{a.requestViewer.set(viewer);java.util.Iterator<String> ids=queued.keys();java.util.ArrayList<String> sent=new java.util.ArrayList<>();while(ids.hasNext()){String id=ids.next();if(!account.equals(a.uid))return;try{a.request("POST","/v8/progress",queued.getJSONObject(id),a.token);sent.add(id);}catch(Exception ignored){}}try{JSONObject latest=new JSONObject(a.prefs.getString(key,"{}"));for(String id:sent)if(latest.has(id)&&latest.getJSONObject(id).toString().equals(queued.getJSONObject(id).toString()))latest.remove(id);a.prefs.edit().putString(key,latest.toString()).apply();}catch(Exception ignored){}}finally{a.requestViewer.remove();a.runOnUiThread(()->{if(page==a.generation)done.run();});}});}
 void syncProgress(boolean force){if(a.video==null||a.playingEpisode<=0||a.activeShow==null||!a.activeShow.optString("status").equals("approved"))return;long now=System.currentTimeMillis();if(!force&&now-lastSync<15000)return;int duration=a.video.getDuration();if(duration<=0)return;lastSync=now;int position=Math.max(0,Math.min(duration,a.video.getCurrentPosition()));final String token=a.token,viewer=a.viewerToken,key=a.local("pending_progress"),account=a.uid;final int id=a.playingEpisode;final boolean completed=position>=duration*.95;try{JSONObject payload=a.obj("episode_id",id,"position_ms",position,"duration_ms",duration,"completed",completed,"observed_at",java.time.Instant.ofEpochMilli(now).toString());JSONObject queued=pending();queued.put(String.valueOf(id),payload);a.prefs.edit().putString(key,queued.toString()).apply();if(a.drama.episode!=null&&a.drama.episode.optBoolean("offline")||token.isEmpty())return;a.io.execute(()->{if(!account.equals(a.uid))return;try{a.requestViewer.set(viewer);a.request("POST","/v8/progress",payload,token);JSONObject saved=new JSONObject(a.prefs.getString(key,"{}"));JSONObject latest=saved.optJSONObject(String.valueOf(id));if(latest!=null&&latest.toString().equals(payload.toString())){saved.remove(String.valueOf(id));a.prefs.edit().putString(key,saved.toString()).apply();}}catch(Exception ignored){}finally{a.requestViewer.remove();}});}catch(Exception ignored){}}

