 void captureLink(Intent intent){Uri uri=intent==null?null:intent.getData();if(uri!=null&&"cineo".equals(uri.getScheme())&&"profile".equals(uri.getHost())){String id=uri.getLastPathSegment();if(id!=null&&id.matches("[a-f0-9-]{36}"))deepProfile=id;}if(uri!=null&&"cineo".equals(uri.getScheme())&&"show".equals(uri.getHost()))try{deepShow=Integer.parseInt(uri.getLastPathSegment());String value=uri.getQueryParameter("episode");deepEpisode=value==null?0:Integer.parseInt(value);}catch(Exception ignored){deepShow=0;}}
